-- taktelio:pre-cli migration
-- Applied manually before this repository adopted the Supabase CLI. Reconstructed from
-- supabase_migrations.schema_migrations. The fresh-install assembly uses db/*.sql instead.

create table public.sc27_members (user_id uuid primary key references auth.users(id) on delete cascade, role text not null default 'trainer' check(role in ('trainer','admin'))); alter table public.sc27_members enable row level security; grant select on public.sc27_members to authenticated; create policy own_membership on public.sc27_members for select to authenticated using(user_id=(select auth.uid())); grant select,insert on public.sc27_exercises to authenticated; grant select,insert,delete on public.sc27_plans to authenticated; create policy member_catalog_read on public.sc27_exercises for select to authenticated using(exists(select 1 from public.sc27_members where user_id=(select auth.uid()))); create policy member_draft_insert on public.sc27_exercises for insert to authenticated with check(created_by=(select auth.uid())::text and payload->>'status'='unreviewed' and exists(select 1 from public.sc27_members where user_id=(select auth.uid()))); create policy own_plan_read on public.sc27_plans for select to authenticated using(owner_id=(select auth.uid())::text and exists(select 1 from public.sc27_members where user_id=(select auth.uid()))); create policy own_plan_insert on public.sc27_plans for insert to authenticated with check(owner_id=(select auth.uid())::text and exists(select 1 from public.sc27_members where user_id=(select auth.uid()))); create policy own_plan_delete on public.sc27_plans for delete to authenticated using(owner_id=(select auth.uid())::text and exists(select 1 from public.sc27_members where user_id=(select auth.uid())));

